// Solo los avisos que todavía no han pasado (si ninguno, avisa a la hora)
const avisosFuturos = (ini, avisos) => { const f = avisos.filter(m => ini.minus({ minutes: m }) > ahora); return f.length ? f : [0]; };
const limpiarTitulo = s => {
  let t = String(s || '').trim().replace(/^(tengo\s+pendientes?\s+(de\s+)?|tengo\s+que\s+|debo\s+|necesito\s+|hay\s+que\s+|recu[eé]rdame\s+(que\s+)?)/i, '').trim();
  return t.charAt(0).toUpperCase() + t.slice(1);
