// Evento de Google Calendar con sus avisos y repetición
const cuerpoEvento = (titulo, ini, avisos, repetir, descripcion) => {
  const f = "yyyy-MM-dd'T'HH:mm:ss";
  const ev = {
    summary: titulo, description: descripcion,
    start: { dateTime: ini.toFormat(f), timeZone: tz },
    end: { dateTime: ini.plus({ minutes: 30 }).toFormat(f), timeZone: tz },
    reminders: { useDefault: false, overrides: avisos.map(m => ({ method: 'popup', minutes: m })) }
  };
  const freq = { diario: 'DAILY', semanal: 'WEEKLY', mensual: 'MONTHLY', anual: 'YEARLY' }[repetir];
  if (freq) ev.recurrence = ['RRULE:FREQ=' + freq];
  return ev;
};
// Filas de avisos para la pestaña Recordatorios (una por cada aviso)
const filasAviso = (base, titulo, inicioTxt, repetir, avisos, idPend, idCal, sync) => {
  const unidad = { diario: 'days', semanal: 'weeks', mensual: 'months', anual: 'years' }[repetir];
  const origen = aFecha(inicioTxt);
  const filas = [];
  const fila = (ev, min, aviso) => ({
    ID: `${base}-${filas.length + 1}`, Mensaje: titulo, 'Fecha evento': ev.toFormat(F), Repetir: repetir,
    'Antelación (min)': min, 'Próximo aviso': aviso.toFormat(F), Estado: 'Activo', 'ID pendiente': idPend,
    'ID Calendar': idCal, Creado: ahora.toFormat(F), Sync: sync, 'ID mensaje aviso': '', Modificado: ahora.toFormat(F)
  });
  for (const min of avisos) {
    let ev = origen, aviso = ev.minus({ minutes: min }), k = 0;
    if (unidad) { while (aviso < ahora && k < 2000) { k++; ev = origen.plus({ [unidad]: k }); aviso = ev.minus({ minutes: min }); } }
    else if (aviso < ahora) continue;
    filas.push(fila(ev, min, aviso));
  }
  if (!filas.length) filas.push(fila(origen, 0, origen < ahora ? ahora : origen));
  return filas;
};

// Unifica la acción (venga de la IA, de un botón o de un atajo), aplica redes de seguridad y decide si hay que preguntar.
// Un mensaje puede traer VARIAS acciones de tipos distintos: el flujo vuelve a este nodo una vez por acción ($runIndex = vuelta).
const n = $('Normalizar').first().json;
const ctx = $('Contexto').first().json;
// Acciones admitidas por el Switch Acción y respuestas internas.
const validas = new Set(["crear_pendientes", "listar_pendientes", "completar_pendientes", "fecha_pendiente", "crear_recordatorios", "listar_recordatorios", "cancelar_recordatorio", "guardar_clave", "consultar_clave", "cancelar_todos_recordatorios", "ver_agenda", "posponer", "crear_repetida", "completar_repetida", "cancelar_repetida", "cancelar_pendiente", "charla", "varias", "aclarar", "error_ia"]);
const esObjeto = x => x !== null && typeof x === 'object' && !Array.isArray(x);
const normalizarAccion = valor => {
  const d = esObjeto(valor) ? { ...valor } : {};
  let accion = d.accion;
  if (esObjeto(accion)) {
    let campos = accion;
    const nombre = [accion.accion, accion.tipo, accion.nombre].find(x => typeof x === 'string' && x.trim());
    if (nombre) accion = nombre;
