  if (accion === 'completar_pendiente' && !Object.prototype.hasOwnProperty.call(d, 'ids')) d.ids = d.id ? [d.id] : [];
  const alias = { crear_pendiente: 'crear_pendientes', crear_varios_pendientes: 'crear_pendientes', crear_recordatorio: 'crear_recordatorios', crear_varios_recordatorios: 'crear_recordatorios', completar_pendiente: 'completar_pendientes', completar_varios: 'completar_pendientes' };
