}

const dicho = (($('Texto a procesar').isExecuted ? $('Texto a procesar').first().json.texto : '') + ' ' + (base.transcripcion || ''));
const t = dicho.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const idDe = c => {
  if (c == null) return null;
  const p = ctx.pendientes.find(x => x.codigo === String(c).replace(/\s+/g, '').toUpperCase() || String(x.ID) === String(c).trim());
  return p ? p.ID : null;
};

// ---------- Lista de acciones del mensaje ----------
let lista = base.accion === 'varias' && Array.isArray(base.acciones)
