// Lo que necesita confirmación va al final, para que lo demás ya quede hecho antes de preguntar
const riesgo = x => ['cancelar_todos_recordatorios', 'aclarar'].includes(x.accion);
lista = lista.map((x, i) => ({ x, i })).sort((p, q) => riesgo(p.x) - riesgo(q.x) || p.i - q.i).map(o => o.x);
const total = lista.length;
let d = { ...lista[Math.min(k, total - 1)] };
let a = String(d.accion || 'charla');

if (libre && total === 1) {
  // Red 1: "ya hice P1, P3" → completar esos pendientes, diga lo que diga la IA
  const codigos = [...t.matchAll(/\bp\s?(\d{1,3})\b/g)].map(m => 'P' + m[1]);
