  // Red 2: "tengo que…/tengo pendiente…/debo…" sin "recuérdame/avísame" → pendiente
  if (['crear_recordatorio', 'crear_varios_recordatorios', 'crear_recordatorios'].includes(a)) {
    if (/(tengo\s+que|tengo\s+pendiente|debo|necesito|hay\s+que)/.test(t) && !/(recuerd|avis|no\s+se\s+me\s+olvide|no\s+me\s+dejes)/.test(t)) {
      const lr = a === 'crear_recordatorio' ? [{ mensaje: d.mensaje, fecha_evento: d.fecha_evento, avisos_min: d.avisos_min }] : (d.recordatorios || []);
      d.pendientes = lr.map(r => ({ pendiente: r.mensaje, fecha_limite: r.fecha_evento || null, avisos_min: (r.avisos_min || []).some(m => Number(m) > 0) ? r.avisos_min : null }));
      a = 'crear_varios_pendientes';
    }
  }
  // Red 3: charla ante una pregunta sobre sus pendientes o recordatorios → mostrar la lista
