if (!filas.length) return [{ json: { sin_avisos: true } }];
return filas.map(r => ({ json: { ID: r.ID } }));

const tzT = 'America/Bogota';
const hoyT = DateTime.now().setZone(tzT);
const aDT = s => DateTime.fromFormat(String(s || '').trim(), 'yyyy-MM-dd H:mm', { zone: tzT });
// "hoy a las 3:00 p. m.", "mañana a las 9:00 a. m.", "el viernes a la 1:00 p. m."
const cuando = s => {
  const d = typeof s === 'string' ? aDT(s) : s;
  if (!d || !d.isValid) return String(s);
  const e = d.setLocale('es');
  const dias = Math.round(e.startOf('day').diff(hoyT.startOf('day'), 'days').days);
  const dia = dias === 0 ? 'hoy' : dias === 1 ? 'mañana' : (dias > 1 && dias < 7) ? 'el ' + e.toFormat('cccc') : 'el ' + e.toFormat("cccc d 'de' LLLL");
  return `${dia} a la${e.hour % 12 === 1 ? '' : 's'} ${e.toFormat('h:mm a')}`;
};
const unir = arr => arr.length <= 1 ? (arr[0] || '') : arr.slice(0, -1).join(', ') + ' y ' + arr[arr.length - 1];
// [1440, 120] → "el día antes y 2 horas antes"; [0] → ""
const avisosTxt = avisos => {
  const t = (avisos || []).filter(m => m > 0).map(m => m === 1440 ? 'el día antes' : m % 1440 === 0 ? `${m / 1440} días antes` : m === 60 ? '1 hora antes' : m % 60 === 0 ? `${m / 60} horas antes` : `${m} minutos antes`);
  return t.length ? unir(t) : '';
};
const esHoy = s => { const d = aDT(s); return d.isValid && d.hasSame(hoyT, 'day'); };

const d = $('Plan').first().json;
const ctx = $('Contexto').first().json;
const hechos = $input.all().map(i => i.json).filter(x => x.ID);
if (!hechos.length) return [{ json: { respuesta: 'Mmm, no encontré ese pendiente. Escribe "mis pendientes" y me dices cuál es.' } }];
const nombres = hechos.map(p => `"${p.Pendiente}"`);
let t = hechos.length === 1 ? `¡Listo! Taché ${nombres[0]}.` : `¡Bien! Taché ${hechos.length}: ${unir(nombres)}.`;
if ((d.pedidos || 0) > hechos.length) t += ` (No encontré ${d.pedidos - hechos.length} de los que mencionaste.)`;
const ids = new Set(hechos.map(h => h.ID));
const quedan = ctx.pendientes.filter(p => !ids.has(p.ID));
const hoyQ = quedan.filter(p => esHoy(p['Fecha límite'])).length;
const teniaHoy = ctx.pendientes.filter(p => esHoy(p['Fecha límite'])).length;
if (teniaHoy) t += hoyQ ? `\nTe ${hoyQ === 1 ? 'queda 1 pendiente' : 'quedan ' + hoyQ + ' pendientes'} para hoy.` : '\nYa no te queda nada para hoy 🎉';
else if (quedan.length) t += `\nTe ${quedan.length === 1 ? 'queda 1 pendiente' : 'quedan ' + quedan.length + ' pendientes'} en total.`;
else t += '\n¡No te queda ningún pendiente! 🎉';
return [{ json: { respuesta: t } }];

const tz = 'America/Bogota';
const F = 'yyyy-MM-dd HH:mm';
const ahora = DateTime.now().setZone(tz);
const sello = ahora.toFormat('yyMMddHHmmss');
const aFecha = s => DateTime.fromFormat(String(s || '').trim(), 'yyyy-MM-dd H:mm', { zone: tz });
// Solo los avisos que todavía no han pasado (si ninguno, avisa a la hora)
const avisosFuturos = (ini, avisos) => { const f = avisos.filter(m => ini.minus({ minutes: m }) > ahora); return f.length ? f : [0]; };
const limpiarTitulo = s => {
  let t = String(s || '').trim().replace(/^(tengo\s+pendientes?\s+(de\s+)?|tengo\s+que\s+|debo\s+|necesito\s+|hay\s+que\s+|recu[eé]rdame\s+(que\s+)?)/i, '').trim();
  return t.charAt(0).toUpperCase() + t.slice(1);
};
const limpiarAvisos = (lista, defecto) => {
  let av = Array.isArray(lista) ? lista : (lista != null ? [lista] : []);
  av = [...new Set(av.map(Number).filter(n => Number.isFinite(n) && n >= 0 && n <= 40320))].sort((a, b) => b - a).slice(0, 5);
  return av.length ? av : defecto;
};
// Evento de Google Calendar con sus avisos y repetición
const cuerpoEvento = (titulo, ini, avisos, repetir, descripcion) => {
  const f = "yyyy-MM-dd'T'HH:mm:ss";
  const ev = {
    summary: titulo, description: descripcion,
    start: { dateTime: ini.toFormat(f), timeZone: tz },
    end: { dateTime: ini.plus({ minutes: 30 }).toFormat(f), timeZone: tz },
    reminders: { useDefault: false, overrides: avisos.map(m => ({ method: 'popup', minutes: m })) }
  };
  const freq = { diario: 'DAILY', semanal: 'WEEKLY', mensual: 'MONTHLY', anual: 'YEARLY' }[repetir];
  if (freq) ev.recurrence = ['RRULE:FREQ=' + freq];
  return ev;
};
// Filas de avisos para la pestaña Recordatorios (una por cada aviso)
const filasAviso = (base, titulo, inicioTxt, repetir, avisos, idPend, idCal, sync) => {
  const unidad = { diario: 'days', semanal: 'weeks', mensual: 'months', anual: 'years' }[repetir];
  const origen = aFecha(inicioTxt);
  const filas = [];
  const fila = (ev, min, aviso) => ({
    ID: `${base}-${filas.length + 1}`, Mensaje: titulo, 'Fecha evento': ev.toFormat(F), Repetir: repetir,
    'Antelación (min)': min, 'Próximo aviso': aviso.toFormat(F), Estado: 'Activo', 'ID pendiente': idPend,
    'ID Calendar': idCal, Creado: ahora.toFormat(F), Sync: sync, 'ID mensaje aviso': '', Modificado: ahora.toFormat(F)
  });
  for (const min of avisos) {
    let ev = origen, aviso = ev.minus({ minutes: min }), k = 0;
    if (unidad) { while (aviso < ahora && k < 2000) { k++; ev = origen.plus({ [unidad]: k }); aviso = ev.minus({ minutes: min }); } }
    else if (aviso < ahora) continue;
    filas.push(fila(ev, min, aviso));
  }
  if (!filas.length) filas.push(fila(origen, 0, origen < ahora ? ahora : origen));
  return filas;
};

// Nueva fecha límite para un pendiente existente
