  const base = `R${sello}-${i + 1}`;
  out.push({ json: {
    ID: base, titulo, fecha_evento: ini.toFormat(F), repetir, avisos,
    evento: cuerpoEvento('⏰ ' + titulo, ini, avisos, repetir, 'Recordatorio creado por el Asistente'),
    filas: filasAviso(base, titulo, ini.toFormat(F), repetir, avisos, '', '', 'Procesando')
  } });
});
if (!out.length) return [{ json: { vacio: true, pedidos: lista.length } }];
return out;

